using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 renamed "Discriminator" to "$type". Preserve the old
            // property name so existing 500K documents remain readable and
            // direct SQL queries against c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the id format from "EntityName|<key>" to
            // "<key>". Preserve the old format so lookups against existing
            // documents succeed.
            entity.HasIdProperty(p => p.Id)
                  .HasIdJsonPropertyName("id");
        });

        // Keep the EF Core 8 id‑value convention: "Product|<key>"
        modelBuilder.Entity<Product>().Property(p => p.Id)
            .HasConversion(
                id => $"Product|{id}",
                str => int.Parse(str.Replace("Product|", "")));
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

